import React from 'react';

export default function WarningModal({ open, title, message, onClose, primaryLabel = 'OK' }) {
  if (!open) return null;
  return (
    <div className="overlay">
      <div className="modal">
        <div className="modal-head">
          <div className="modal-title">{title || 'Warning'}</div>
          <button className="login-history-close" onClick={onClose}>×</button>
        </div>
        <div className="modal-body">
          <p style={{ marginBottom: 12 }}>{message}</p>
          <div style={{ fontSize: 13, color: 'var(--t2)' }}>If you believe this is an error, contact your administrator.</div>
        </div>
        <div className="modal-foot">
          <button className="btn btn-outline" onClick={onClose}>{primaryLabel}</button>
        </div>
      </div>
    </div>
  );
}
